create table public.community_recipes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, author_name text not null check(char_length(btrim(author_name)) between 2 and 60), title text not null check(char_length(btrim(title)) between 3 and 120), description text not null default '' check(char_length(description)<=800), category text not null check(category in ('Hlavní jídla','Polévky','Bez masa','Dezerty','Snídaně','Ostatní')), minutes integer not null check(minutes between 1 and 1440), servings integer not null check(servings between 1 and 50), ingredients text[] not null check(cardinality(ingredients) between 1 and 60 and char_length(array_to_string(ingredients,''))<=12000 and array_position(ingredients,null) is null and array_position(ingredients,'') is null), steps text[] not null check(cardinality(steps) between 1 and 40 and char_length(array_to_string(steps,''))<=16000 and array_position(steps,null) is null and array_position(steps,'') is null), image_path text check(image_path is null or (image_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.webp$' and split_part(image_path,'/',1)=user_id::text)), published boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.community_recipes enable row level security; create index community_recipes_user_id_idx on public.community_recipes(user_id); create index community_recipes_public_created_idx on public.community_recipes(created_at desc) where published; grant select on public.community_recipes to anon,authenticated; grant insert(id,user_id,author_name,title,description,category,minutes,servings,ingredients,steps,image_path,published) on public.community_recipes to authenticated; grant update(author_name,title,description,category,minutes,servings,ingredients,steps,image_path,published,updated_at) on public.community_recipes to authenticated; grant delete on public.community_recipes to authenticated; create policy recipes_read_published on public.community_recipes for select to anon,authenticated using(published); create policy recipes_read_own on public.community_recipes for select to authenticated using(user_id=(select auth.uid())); create policy recipes_insert_own on public.community_recipes for insert to authenticated with check(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous'),'false')='false'); create policy recipes_update_own on public.community_recipes for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid())); create policy recipes_delete_own on public.community_recipes for delete to authenticated using(user_id=(select auth.uid())); insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('recipe-images','recipe-images',true,2097152,array['image/webp']); create policy recipe_images_insert_own on storage.objects for insert to authenticated with check(bucket_id='recipe-images' and (storage.foldername(name))[1]=(select auth.uid()::text)); create policy recipe_images_delete_own on storage.objects for delete to authenticated using(bucket_id='recipe-images' and owner_id=(select auth.uid()::text)); create policy recipe_images_read_own on storage.objects for select to authenticated using(bucket_id='recipe-images' and owner_id=(select auth.uid()::text));
